(async()=>{const out=[],wait=ms=>new Promise(r=>setTimeout(r,ms)),el=document.createElement('div');document.body.append(el);el.style.cssText='opacity:0.4;width:12px;transform:translateX(3px)';const read=()=>({opacity:getComputedStyle(el).opacity,width:getComputedStyle(el).width,transform:getComputedStyle(el).transform});const before=read(),a=el.animate([{opacity:0,width:'10px',transform:'translateX(0px)'},{opacity:1,width:'200px',transform:'translateX(100px)'}],{duration:1e9,fill:'forwards',iterations:Infinity});out.push(['start',{before,after:read(),state:a.playState,all:el.getAnimations().length}]);await a.finished;out.push(['after-finished',{style:read(),state:a.playState,all:el.getAnimations().length}]);a.cancel();out.push(['after-cancel',{style:read(),state:a.playState}]);
for(const mode of['play','reverse']){const a=el.animate();a.finished.catch(()=>{});const events=[];a.onfinish=()=>events.push('finished');setTimeout(()=>{a[mode]();events.push('acted')},6);setTimeout(()=>events.push('middle:'+a.playState),12);await wait(35);out.push(['timer:'+mode,events]);a.cancel();}
for(const mode of['replace','clear-and-replace']){const a=el.animate(),events=[];a.addEventListener('finish',()=>events.push('first'));a.onfinish=()=>events.push('old');a.addEventListener('finish',()=>events.push('last'));if(mode==='clear-and-replace')a.onfinish=null;a.onfinish=()=>events.push('new');a.finish();await wait(20);out.push(['handler-order:'+mode,events]);}
{const a=el.animate();a.pause();const events=[];a.onfinish=e=>{events.push(['handler',e.defaultPrevented]);return false};a.addEventListener('finish',e=>events.push(['listener',e.defaultPrevented]));const e=new AnimationPlaybackEvent('finish',{cancelable:true});out.push(['handler-return',{returned:a.dispatchEvent(e),prevented:e.defaultPrevented,events}]);a.finished.catch(()=>{});a.cancel();}
{const gets=[],init=new Proxy({currentTime:2,timelineTime:3},{get(t,k){gets.push(String(k));return t[k]}});const e=new AnimationPlaybackEvent({toString(){gets.push('type');return'x'}},init);out.push(['event-order',{gets,currentTime:e.currentTime,timelineTime:e.timelineTime}]);}
return out;})()
